export class ButtonStateManager {
  /**
   * Predefined spinner styles
   */
  static SPINNER_STYLES = {
    DEFAULT: "<div class='spinner-border spinner-border-sm text-dark'></div>",
    DANGER: "<div class='spinner-border spinner-border-sm text-danger'></div>",
    SUCCESS: "<div class='spinner-border spinner-border-sm text-success'></div>",
  };

  /**
   * Constructor
   * @param {HTMLElement} buttonElement - The button element to manage
   * @param {string} spinnerType - Spinner type ('DEFAULT', 'DANGER', 'SUCCESS') or custom HTML string
   */
  constructor(buttonElement, spinnerType = 'DEFAULT') {
    this.button = buttonElement;
    this.spinnerHTML = ButtonStateManager.SPINNER_STYLES[spinnerType] || spinnerType;
    this.originalWidth = null;
    this.originalHTML = null;
  }

  /**
   * Show spinner and disable button
   */
  showSpinner() {
    this.originalWidth = this.button.offsetWidth;
    this.originalHTML = this.button.innerHTML;
    this.button.style.width = `${this.originalWidth}px`;
    this.button.innerHTML = this.spinnerHTML;
    this.button.disabled = true;
  }

  /**
   * Restore button to original state
   */
  restore() {
    if (this.originalHTML) {
      this.button.innerHTML = this.originalHTML;
      this.button.disabled = false;
    }
  }
}
